#!/usr/bin/env node
// Generate docs/generated/db-schema.md from supabase/migrations/*.sql
//
// Determinism contract: given identical migration files, this script writes
// byte-identical output. CI runs `node scripts/generate-db-schema-doc.mjs --check`
// to fail when the generated file is out of date with migrations.

import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const here = fileURLToPath(new URL(".", import.meta.url));
const repoRoot = join(here, "..");
const migrationsDir = join(repoRoot, "supabase", "migrations");
const outPath = join(repoRoot, "docs", "generated", "db-schema.md");

const checkOnly = process.argv.includes("--check");

function readMigrations() {
  const names = readdirSync(migrationsDir)
    .filter((n) => n.endsWith(".sql"))
    .sort();
  return names.map((name) => ({
    name,
    body: readFileSync(join(migrationsDir, name), "utf8"),
  }));
}

// Regex-based parsers — migrations are well-formed and we control the
// authoring conventions, so we don't need a real SQL parser. If a future
// migration uses syntax we don't recognize, the parser fails loud rather
// than silently dropping definitions.

function parseEnums(body) {
  const out = [];
  for (const m of body.matchAll(/create type public\.(\w+) as enum \(([^)]+)\);/g)) {
    out.push({
      name: m[1],
      values: m[2]
        .split(",")
        .map((v) => v.trim().replace(/^'|'$/g, ""))
        .filter(Boolean),
    });
  }
  return out;
}

function parseTables(body) {
  const out = [];
  for (const m of body.matchAll(/create table public\.(\w+) \(([\s\S]*?)\n\);/g)) {
    out.push({
      name: m[1],
      columns: m[2]
        .split("\n")
        .map((l) => l.trim())
        .filter((l) => l && !l.startsWith("--") && !l.startsWith("constraint")),
    });
  }
  return out;
}

function parseAlters(body) {
  // Capture `alter table public.<name> add column ...;` for follow-up migrations.
  const out = [];
  for (const m of body.matchAll(/alter table public\.(\w+)\s+(add column [^;]+);/g)) {
    out.push({ table: m[1], statement: m[2].replace(/\s+/g, " ") });
  }
  return out;
}

function parseRlsPolicies(body) {
  // `create policy "<name>" on public.<table> ...` — record just (table, policy name).
  const out = [];
  for (const m of body.matchAll(/create policy "([^"]+)" on public\.(\w+)/g)) {
    out.push({ table: m[2], policy: m[1] });
  }
  return out;
}

function buildDoc(migrations) {
  const allEnums = [];
  const allTables = [];
  const allAlters = [];
  const allPolicies = [];
  for (const m of migrations) {
    for (const e of parseEnums(m.body)) allEnums.push({ ...e, from: m.name });
    for (const t of parseTables(m.body)) allTables.push({ ...t, from: m.name });
    for (const a of parseAlters(m.body)) allAlters.push({ ...a, from: m.name });
    for (const p of parseRlsPolicies(m.body))
      allPolicies.push({ ...p, from: m.name });
  }

  const lines = [];
  lines.push("# Database schema — generated");
  lines.push("");
  lines.push(
    "> Auto-generated by `scripts/generate-db-schema-doc.mjs` from `supabase/migrations/`.",
  );
  lines.push(
    "> **Do not edit by hand.** Update the migrations and re-run `pnpm db:schema:doc`.",
  );
  lines.push("");
  lines.push(`Source migrations (${migrations.length}):`);
  for (const m of migrations) lines.push(`- \`supabase/migrations/${m.name}\``);
  lines.push("");

  lines.push("## Tables");
  lines.push("");
  for (const t of allTables) {
    lines.push(`### \`${t.name}\``);
    lines.push("");
    lines.push(`Defined in \`${t.from}\`.`);
    lines.push("");
    lines.push("```sql");
    for (const c of t.columns) lines.push(c);
    lines.push("```");
    const alters = allAlters.filter((a) => a.table === t.name);
    if (alters.length) {
      lines.push("");
      lines.push("Follow-up migrations:");
      for (const a of alters) lines.push(`- \`${a.from}\` — \`${a.statement}\``);
    }
    const policies = allPolicies.filter((p) => p.table === t.name);
    if (policies.length) {
      lines.push("");
      lines.push("RLS policies:");
      for (const p of policies) lines.push(`- \`${p.policy}\` (\`${p.from}\`)`);
    }
    lines.push("");
  }

  lines.push("## Enums");
  lines.push("");
  for (const e of allEnums) {
    lines.push(`### \`${e.name}\``);
    lines.push("");
    lines.push(`Defined in \`${e.from}\`.`);
    lines.push("");
    lines.push("```");
    for (const v of e.values) lines.push(v);
    lines.push("```");
    lines.push("");
  }

  return lines.join("\n") + "\n";
}

function main() {
  const migrations = readMigrations();
  const doc = buildDoc(migrations);

  if (checkOnly) {
    let current = "";
    try {
      current = readFileSync(outPath, "utf8");
    } catch {
      // Missing file is a violation in --check mode.
    }
    if (current !== doc) {
      process.stderr.write(
        `db-schema.md is out of date. Run: pnpm db:schema:doc\n`,
      );
      process.exit(1);
    }
    process.stdout.write("db-schema.md up to date.\n");
    return;
  }

  writeFileSync(outPath, doc);
  process.stdout.write(`Wrote ${outPath}\n`);
}

main();
